import copy
import gc
import hashlib
import json
import os
from pathlib import Path
import platform
import shutil
import statistics
import tempfile
import time
from unittest.mock import patch
from proworksim.storage import Store, atomic_write, json_bytes
from proworksim import storage
from proworksim import software_benchmark_world_v054 as original_world

checks = {}
report = {'version': 'v054-state-cache-control-r1', 'python': platform.python_version(), 'model_calls': 0, 'gpu_launches': 0, 'source_world_mutated': False, 'checks': checks}
def passed(name, value):
    checks[name] = bool(value)
    if not value:
        raise AssertionError(name)
def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()
def measured(callback):
    started = time.perf_counter()
    result = callback()
    return result, time.perf_counter()-started

with tempfile.TemporaryDirectory(prefix='v054-state-cache-control-') as directory:
    root = Path(directory)
    basic = root/'semantic'
    (basic/'control').mkdir(parents=True)
    base, candidate = Store(basic), CachedStateStore(basic)
    shared = ['original']
    input_state = {'tuple': (1, 2), 'alias_a': shared, 'alias_b': shared, 7: {'nested': ['A']}}
    base.save(input_state)
    original_bytes = (basic/'control/state.json').read_bytes()
    cached = candidate.load()
    passed('normalization_matches_real_json_roundtrip', cached == json.loads(original_bytes) and cached['alias_a'] is not cached['alias_b'] and isinstance(cached['tuple'], list) and '7' in cached)
    left, right = candidate.load(), candidate.load()
    left['7']['nested'].append('unsaved')
    passed('independent_load_returns', right['7']['nested'] == ['A'] and left is not right and left['7'] is not right['7'])
    try:
        unsaved = candidate.load()
        unsaved['alias_a'].append('exception')
        raise RuntimeError('synthetic unsaved transaction')
    except RuntimeError:
        pass
    passed('exception_without_save_does_not_leak', candidate.load() == json.loads(original_bytes))
    fsync_calls = []
    real_fsync = storage.os.fsync
    def observed_fsync(fd):
        fsync_calls.append(fd)
        return real_fsync(fd)
    with patch.object(storage.os, 'fsync', observed_fsync):
        candidate.save(input_state)
    passed('save_bytes_exactly_match_original_writer', (basic/'control/state.json').read_bytes() == original_bytes)
    passed('original_fsync_and_private_file_mode_preserved', len(fsync_calls) == 1 and (basic/'control/state.json').stat().st_mode & 0o777 == 0o600)
    passed('save_invalidates_without_caching_input', candidate._state_cache is None)
    candidate.load()
    old_info = (basic/'control/state.json').stat()
    replacement = json.loads(original_bytes)
    replacement['7']['nested'] = ['B']
    atomic_write(basic/'control/state.json', json_bytes(replacement))
    os.utime(basic/'control/state.json', ns=(old_info.st_atime_ns, old_info.st_mtime_ns))
    passed('external_atomic_replace_even_same_size_mtime_invalidates', (basic/'control/state.json').stat().st_size == len(original_bytes) and candidate.load() == replacement)
    replacement['7']['nested'] = ['C']
    old_info = (basic/'control/state.json').stat()
    time.sleep(.02)  # This filesystem's ctime has a ~4ms clock tick.
    with (basic/'control/state.json').open('r+b') as stream:
        stream.write(json_bytes(replacement))
        stream.flush()
        os.fsync(stream.fileno())
    os.utime(basic/'control/state.json', ns=(old_info.st_atime_ns, old_info.st_mtime_ns))
    passed('same_inode_observable_ctime_change_invalidates', (basic/'control/state.json').stat().st_ctime_ns != old_info.st_ctime_ns and candidate.load() == replacement)
    persisted = (basic/'control/state.json').read_bytes()
    bad = candidate.load()
    bad['bad'] = float('nan')
    try:
        candidate.save(bad)
    except ValueError:
        pass
    else:
        raise AssertionError('NaN must still be rejected by original json_bytes')
    passed('failed_save_preserves_original_bytes_and_load', (basic/'control/state.json').read_bytes() == persisted and candidate.load() == json.loads(persisted))
    calls = []
    original_copy = copy.deepcopy
    replacement['7']['nested'] = ['D']
    def racing_copy(value):
        if not calls:
            calls.append(True)
            atomic_write(basic/'control/state.json', json_bytes(replacement))
        return original_copy(value)
    with patch.object(copy, 'deepcopy', racing_copy):
        observed = candidate.load()
    passed('stat_after_copy_detects_foreign_replace', observed == replacement)
    passed('cache_has_only_one_committed_snapshot', isinstance(candidate._state_cache, tuple) and len(candidate._state_cache) == 2)

    source = Path('/data0/zhuxinrui/projects/ProWorkSim/runs/software-benchmark-v054/formal-queue-r1/slots/6/preclaim-1/episode/managed-world/world')
    state_source = source/'control/state.json'
    benchmark = root/'benchmark'
    (benchmark/'control').mkdir(parents=True)
    shutil.copyfile(state_source, benchmark/'control/state.json')
    standard, fast = Store(benchmark), CachedStateStore(benchmark)
    _, cold = measured(fast.load)
    timings = {'cached_cold_load': cold, 'standard_load': [], 'cached_warm_load': []}
    for _ in range(3):
        for label, store in [('standard_load', standard), ('cached_warm_load', fast)]:
            gc.collect()
            value, duration = measured(store.load)
            timings[label].append(duration)
            del value
    report['state_only_benchmark'] = {'source': str(state_source), 'bytes': state_source.stat().st_size, 'timings_seconds': timings, 'warm_read_reduction_fraction': 1-statistics.median(timings['cached_warm_load'])/statistics.median(timings['standard_load']), 'caveat': 'Warm file, isolated CPU, three read pairs; not overall PROJECT speedup. Save remains original full serialization/atomic_write/fsync.'}
    del standard, fast
    gc.collect()

    # One real public read_task transaction per identical independent copy.
    # Fix only the timing receipt and request identity for byte comparison;
    # duration measurement below uses unmodified perf_counter.
    transaction_rows = []
    outputs = []
    for label, cls in [('original', original_world.SoftwareCollaborationWorld), ('cached', CandidateWorld)]:
        target = root/('world-'+label)
        shutil.copytree(source, target, symlinks=True)
        world = cls(target)
        with world.store.lock():
            world.state = world.store.load()
        component = {}
        counts = {}
        for name in ('load', 'save', 'recover'):
            original_method = getattr(world.store, name)
            def observed_method(*args, _name=name, _method=original_method, **kwargs):
                started = time.perf_counter()
                try:
                    return _method(*args, **kwargs)
                finally:
                    component[_name] = component.get(_name, 0.0) + time.perf_counter()-started
                    counts[_name] = counts.get(_name, 0) + 1
            setattr(world.store, name, observed_method)
        with patch('proworksim.core.runner.time.monotonic', return_value=1000.0):
            output, elapsed = measured(lambda: world.act(original_world.MEMBERS[0], 'project_action', {'project_id': original_world.PROJECT, 'tool': 'read_task', 'arguments': {}}, request_key='state-cache-equivalence-control'))
        passed(label+'_real_public_read_task_committed', output['ok'] and output['command_committed'])
        outputs.append(output)
        transaction_rows.append({'implementation': label, 'seconds': elapsed, 'store_seconds': component, 'store_calls': counts, 'state_sha256': sha(target/'control/state.json'), 'output_sha256': hashlib.sha256(json_bytes(output)).hexdigest()})
        del world
        gc.collect()
    passed('actual_tool_output_exactly_identical', outputs[0] == outputs[1])
    passed('actual_transaction_state_bytes_identical_with_fixed_timing_receipt', transaction_rows[0]['state_sha256'] == transaction_rows[1]['state_sha256'])
    report['public_transaction_comparison'] = transaction_rows
    report['public_transaction_caveat'] = 'One read_task on each independent completed-world copy, after a priming load. Fixed request_key and monotonic only to compare canonical bytes including wall_seconds; normal production retains actual elapsed timing and is not expected to repeat identical wall_seconds.'
    report['source_state_sha256'] = sha(state_source)
    passed('source_completed_world_bytes_unchanged', report['source_state_sha256'] == 'a0277054e10afe853cd87f94d8ce1cc3490b76bf20d7c7010aa899164229ecb3')
report['passed'] = all(checks.values())
print(json.dumps(report, ensure_ascii=False, indent=2))
